use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input = input.as_array().unwrap();
    let mut finish_times = Vec::new();
    let mut current_finish = 0;
    let mut previous_finish = 0;

    for (arrival, duration) in input {
        current_finish = current_finish.max(arrival);
        finish_times.push(serde_json::Value::from(current_finish));
        previous_finish = current_finish;
    }

    Value::Array(finish_times)
}
